using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json.Nodes;
using Lunos.Core;
using Xunit;

namespace Lunos.Core.Tests
{
    // The shared fixtures (sdks/ide/fixtures/hunks), generated by packages/opencode/test/ide/hunk-fixtures.ts
    // from the same `diff` calls the server makes. The JetBrains tests read the same files.
    public class HunksTests
    {
        public static IEnumerable<object[]> Fixtures() =>
            Directory.GetFiles(FixtureDir(), "*.json").OrderBy(f => f).Select(f => new object[] { Path.GetFileNameWithoutExtension(f) });

        private static string FixtureDir()
        {
            var dir = new DirectoryInfo(AppContext.BaseDirectory);
            while (dir != null && !Directory.Exists(Path.Combine(dir.FullName, "ide", "fixtures", "hunks"))) dir = dir.Parent;
            return Path.Combine(dir?.FullName ?? throw new DirectoryNotFoundException("sdks/ide/fixtures/hunks"), "ide", "fixtures", "hunks");
        }

        private static JsonObject Load(string name) => JsonNode.Parse(File.ReadAllText(Path.Combine(FixtureDir(), name + ".json")))!.AsObject();

        [Fact]
        public void FixturesAreThere() => Assert.True(Fixtures().Count() >= 6);

        [Theory]
        [MemberData(nameof(Fixtures))]
        public void EveryAcceptRejectCombinationGivesExactlyTheExpectedFile(string name)
        {
            var fixture = Load(name);
            var patch = FilePatch.Parse(fixture["patch"]!.GetValue<string>());
            var after = fixture["after"]!.GetValue<string>();
            Assert.Equal(fixture["hunks"]!.GetValue<int>(), patch.Hunks.Count);
            foreach (var c in fixture["cases"]!.AsArray().Select(n => n!.AsObject()))
            {
                var accept = c["accept"]!.AsArray().Select(b => b!.GetValue<bool>()).ToList();
                Assert.Equal(c["expected"]!.GetValue<string>(), patch.Apply(after, accept));
            }
            Assert.Equal(fixture["before"]!.GetValue<string>(), patch.Before(after));
        }

        [Fact]
        public void HunksSayWhereTheyAreAndWhatTheyChange()
        {
            var hunks = FilePatch.Parse(Load("two-hunks")["patch"]!.GetValue<string>()).Hunks;
            Assert.Equal(new[] { 4, 8 }, hunks.Select(h => h.Line));
            Assert.Equal(new[] { "  int Add(int a, int b) { return a + b; }\n" }, hunks[0].Removed);
            Assert.Equal(new[] { "  int Mul(int a, int b) => a * b;\n" }, hunks[1].Added);
        }

        [Fact]
        public void AFileSavedWithABomAppliesAgainstTheServersPatchWhichHasNone()
        {
            var fixture = Load("two-hunks");
            var patch = FilePatch.Parse(fixture["patch"]!.GetValue<string>());
            var path = Path.Combine(Path.GetTempPath(), "lunos-bom-" + Guid.NewGuid().ToString("N") + ".cs");
            File.WriteAllText(path, fixture["after"]!.GetValue<string>(), new System.Text.UTF8Encoding(true));
            try
            {
                var expected = fixture["cases"]![1]!["expected"]!.GetValue<string>();
                Assert.Equal(expected, patch.Apply(FilePatch.WithoutBom(File.ReadAllText(path)), new[] { true, false }));
                Assert.Equal(expected, patch.Apply(FilePatch.WithoutBom("\uFEFF" + fixture["after"]!.GetValue<string>()), new[] { true, false }));
            }
            finally
            {
                File.Delete(path);
            }
        }

        [Fact]
        public void AFileChangedAfterTheEditIsRefusedNotFuzzed()
        {
            var fixture = Load("two-hunks");
            var patch = FilePatch.Parse(fixture["patch"]!.GetValue<string>());
            var edited = fixture["after"]!.GetValue<string>().Replace("class Calc", "class Calculator");
            Assert.Throws<StalePatchException>(() => patch.Apply(edited, new[] { true, false }));
        }
    }
}
